# -*- coding: utf-8 -*-
"""
Глава 1: ТЕОРЕТИЧЕСКИЕ ОСНОВЫ ПОСТРОЕНИЯ РЕКОМЕНДАТЕЛЬНЫХ СИСТЕМ В МУЗЫКАЛЬНОЙ ИНДУСТРИИ
для пояснительной записки «Разработка модуля персонализированных рекомендаций на основе машинного обучения».
"""

from docx.shared import Pt, Mm, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from .styles import add_p, add_h1, add_h2, add_h3, add_table

def build_chapter_1(doc):
    add_h1(doc, "1 ТЕОРЕТИЧЕСКИЕ ОСНОВЫ ПОСТРОЕНИЯ РЕКОМЕНДАТЕЛЬНЫХ СИСТЕМ В МУЗЫКАЛЬНОЙ ИНДУСТРИИ", page_break=True)

    add_h2(doc, "1.1 Анализ предметной области и специфика рекомендательных алгоритмов в музыкальном сегменте")

    add_p(doc, "Современный этап развития цифровой коммерции характеризуется переходом от экстенсивного накопления товарных каталогов к интеллектуализации процессов взаимодействия с пользователем. В сегменте музыкальной индустрии данный переход обусловлен высокой размерностью и смысловой сложностью предметной области. Торговый ассортимент музыкального сектора включает две взаимодополняющие категории: результаты звукозаписи на физических и цифровых носителях, включая виниловые пластинки и компакт-диски, а также электронные аппаратные средства их создания, такие как синтезаторы различных архитектур, электрогитары, грувбоксы и звуковые процессоры.")

    add_p(doc, "Специфика формирования рекомендаций в музыкальной сфере определяется следующими ключевыми аспектами:")

    add_p(doc, "1. Субъективно-тембральный характер предпочтений. В отличие от традиционных потребительских товаров, выбор музыкального инструмента или звукозаписи основывается на тонких акустических характеристиках: частотном балансе, динамическом диапазоне и эмоционально-смысловом характере звучания, которые трудно описать классическими числовыми атрибутами.", first_indent=12.5)

    add_p(doc, "2. Взаимосвязь между произведением и инструментом его создания. Звучание культовых музыкальных произведений неразрывно связано с аппаратными синтезаторами и гитарным оборудованием, на котором формировались конкретные тембры. Например, характерное звучание баса в электронной музыке формируется аналоговыми субтрактивными синтезаторами, а пространственные текстуры в эмбиенте — волновыми и гранулярными архитектурами. Покупатель, интересующийся альбомом определенного жанра, проявляет интерес и к музыкальным инструментам соответствующего типа.", first_indent=12.5)

    add_p(doc, "3. Необходимость структурированного описания музыкальных изданий. Выбор физических релизов на виниле или компакт-дисках в значительной степени определяется составом альбома: списком композиций, их порядком и длительностью звучания. Наличие упорядоченного треклиста позволяет покупателю оценить наполнение релиза непосредственно в карточке товара.", first_indent=12.5)

    add_h2(doc, "1.2 Математические и алгоритмические методы машинного обучения в задачах персонализированного подбора")

    add_p(doc, "В теории и практике машинного обучения для построения рекомендательных систем традиционно используются три базовых подхода:")

    add_p(doc, "1. Коллаборативная фильтрация. Основывается на анализе матрицы взаимодействия покупателей и объектов каталога. Применяются алгоритмы матричной факторизации и поиск похожих пользователей. Главным ограничением данного подхода в специализированном ритейле является проблема «холодного старта»: для новых товаров и редких инструментов история покупок отсутствует, что делает коллаборативные модели малоэффективными.", first_indent=12.5)

    add_p(doc, "2. Контентная фильтрация. Рекомендации строятся на сопоставлении профилей товаров по их явным атрибутам, таким как категория, производитель, число клавиш или материал корпуса. Однако стандартные контентные модели не способны выявлять скрытые смысловые взаимосвязи и стилистическое сходство разнородных объектов каталога.", first_indent=12.5)

    add_p(doc, "3. Векторные семантические представления на основе нейросетевых моделей. Прогрессивный подход, основанный на отображении разнородных сущностей в общее многомерное метрическое пространство с помощью глубоких нейросетевых трансформеров, таких как модель MiniLM. Векторы формируются на основе текстовых описаний, жанрово-стилистических характеристик и атрибутивных профилей. Близость объектов оценивается косинусным сходством, что позволяет сопоставлять музыкальные издания с инструментами звукоизвлечения.", first_indent=12.5)

    add_p(doc, "Для реализации в интернет-магазине «Synthesia» был выбран метод векторных представлений с метрикой косинусного сходства на базе предобученной модели MiniLM-L12-v2 размерностью 384 признака. Данный подход обеспечивает строгое математическое решение задачи сквозного сопоставления разнородных товаров и устойчив к проблеме «холодного старта».")

    add_h2(doc, "1.3 Сравнительный анализ существующих подходов и отечественных программных платформ")

    add_p(doc, "Был выполнен детальный сравнительный анализ действующих торговых площадок музыкального сегмента на рынке Республики Беларусь и Российской Федерации: старейшего белорусского ритейлера музыкальных инструментов Muz.by, специализированного салона звукового оборудования Tvoyzvuk.by, розничной сети гипермаркетов «Музторг» и магазина звуковой аппаратуры и виниловых пластинок «Аудиомания».")

    headers_1_1 = ["Торговая платформа", "Ассортимент каталога", "Структурированный треклист", "Методы рекомендаций", "Сквозной подбор", "Наполнение каталога"]
    data_1_1 = [
        ["Muz.by (Беларусь)", "Инструменты и звук", "Отсутствует", "Статические сопутствующие", "Отсутствует", "Ручной ввод"],
        ["Tvoyzvuk.by (Беларусь)", "Инструменты и студия", "Отсутствует", "Атрибутивные фильтры", "Отсутствует", "Ручной ввод"],
        ["Музторг (РФ)", "Инструменты и звук", "Отсутствует", "По популярности и тегам", "Отсутствует", "Учетные системы 1С"],
        ["Аудиомания (РФ)", "Звуковая техника и винил", "Текстовое описание", "Статистические («с этим берут»)", "Отсутствует", "Импорт от поставщиков"],
        ["Synthesia (проект)", "Инструменты и винил / CD", "Таблица в базе данных", "Векторные эмбеддинги ML", "Да, по семантике векторов", "Модуль synesthesia-parser"]
    ]
    add_table(doc, headers_1_1, data_1_1, col_widths=[28, 30, 30, 32, 28, 28], title="Таблица 1.1 — Сравнительный анализ отечественных музыкальных интернет-магазинов и платформы Synthesia")

    add_p(doc, "Анализ данных Таблицы 1.1 показывает, что существующие отечественные магазины разделены по узким нишам: магазины инструментов Muz.by, Tvoyzvuk.by и «Музторг» не предлагают музыкальных альбомов и не содержат треклистов, а магазины аппаратуры и пластинок, такие как «Аудиомания», ограничиваются простыми статистическими рекомендациями. Ни одна из представленных площадок не осуществляет подбор инструментов для создания музыки к выбранным альбомам и не применяет векторные пространства машинного обучения.")

    add_h2(doc, "1.4 Обоснование выбора архитектурных решений и технологического стека программного комплекса")

    add_p(doc, "Для реализации программного комплекса интернет-магазина «Synthesia» был сформирован технологический стек, ориентированный на производительность, модульность и надежность:")

    add_p(doc, "1. Платформа электронной торговли — OpenCart 3 в сборке LiveStore. Обеспечивает транзакционный учет заказов, управление корзиной и покупателями на основе архитектуры Model-View-Controller, а также модификацию системных функций через технологию OCMOD без прямого изменения файлов ядра.", first_indent=12.5)

    add_p(doc, "2. Реляционная СУБД — MySQL с подсистемой хранения данных InnoDB и интерфейсом подключения mysqli. Отвечает за хранение таблиц каталога, категорий, характеристик, структурированных треклистов и журналов заказов с соблюдением требований целостности ACID.", first_indent=12.5)

    add_p(doc, "3. Подсистема автоматизированного сбора данных synesthesia-parser. Программный комплекс на языке Python 3.13 с использованием библиотеки curl_cffi для защищенного сетевого взаимодействия с ресурсом pop-music.ru, библиотеки BeautifulSoup4 для синтаксического анализа структуры веб-страниц, библиотеки requests с контролем лимитов для взаимодействия с базой Discogs, и Pydantic для валидации структурированных моделей данных.", first_indent=12.5)

    add_p(doc, "4. Модуль векторного кодирования — библиотека SentenceTransformers с предобученной моделью paraphrase-multilingual-MiniLM-L12-v2. Модель формирует плотные 384-мерные векторные представления для текстовых описаний и характеристик товаров, обеспечивая качественное семантическое сопоставление на русском и английском языках.", first_indent=12.5)

    add_p(doc, "5. Сервис векторного поиска и ранжирования — фреймворк FastAPI и векторная база данных Qdrant. Сервис осуществляет индексацию векторов в оперативной памяти Qdrant с организацией графового индекса HNSW и метрикой косинусного расстояния.", first_indent=12.5)

    add_p(doc, "6. Высокопроизводительное кэширование — оперативная база данных Redis. Применяется для промежуточного кэширования результатов рекомендаций, гарантируя отдачу готовых списков за 1–2 миллисекунды.", first_indent=12.5)
